package fr.cercle.tourderole;
import android.app.*;import android.content.*;import android.os.*;import android.content.pm.PackageManager;import org.json.*;
public class AlarmReceiver extends BroadcastReceiver{
public static PendingIntent intent(Context c,String tab,String id,boolean timer){Intent i=new Intent(c,AlarmReceiver.class).setAction("alarm").putExtra("tab",tab).putExtra("id",id).putExtra("timer",timer);return PendingIntent.getBroadcast(c,(id+timer).hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
public static void schedule(Context c,String tab,JSONObject row,long when,boolean timer){((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,Math.max(System.currentTimeMillis()+500,when),intent(c,tab,row.optString("id"),timer));}
public static void cancel(Context c,String id){AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);am.cancel(intent(c,"",id,false));am.cancel(intent(c,"",id,true));c.getSharedPreferences("timers",0).edit().remove(id).remove(id+"_step").apply();}
public static void rebuild(Context c){try{JSONObject db=MainActivity.load(c);java.util.Iterator<String> names=db.keys();while(names.hasNext()){String tab=names.next();JSONArray a=db.optJSONArray(tab);if(a==null)continue;for(int i=0;i<a.length();i++){JSONObject row=a.optJSONObject(i);if(row==null)continue;long alarm=row.optLong("_alarm");if(alarm>System.currentTimeMillis())schedule(c,tab,row,alarm,false);long timer=c.getSharedPreferences("timers",0).getLong(row.optString("id"),0);if(timer>0)schedule(c,tab,row,timer,true);}}}catch(Exception ignored){}}
public void onReceive(Context c,Intent i){if(!"alarm".equals(i.getAction())){rebuild(c);return;}try{JSONObject db=MainActivity.load(c);String tab=i.getStringExtra("tab"),id=i.getStringExtra("id");JSONArray a=db.optJSONArray(tab);if(a==null)return;JSONObject row=null;for(int j=0;j<a.length();j++)if(a.optJSONObject(j).optString("id").equals(id))row=a.optJSONObject(j);if(row==null)return;String body="Échéance prévue aujourd’hui.";if(i.getBooleanExtra("timer",false)){SharedPreferences prefs=c.getSharedPreferences("timers",0);long finish=prefs.getLong(id,0);if(finish==0)return;int step=prefs.getInt(id+"_step",0);long[] durations=Core.durations(row.optString("durees"));step++;if(step<durations.length){long next=System.currentTimeMillis()+durations[step];prefs.edit().putLong(id,next).putInt(id+"_step",step).apply();schedule(c,tab,row,next,true);body="Étape "+step+" terminée. Étape "+(step+1)+" démarrée.";}else{prefs.edit().remove(id).remove(id+"_step").apply();body="Séquence terminée.";}}
NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("reminders","Rappels et minuteurs",NotificationManager.IMPORTANCE_HIGH));if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)return;PendingIntent open=PendingIntent.getActivity(c,id.hashCode(),new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);nm.notify(id.hashCode(),new Notification.Builder(c,"reminders").setSmallIcon(R.drawable.icon).setContentTitle(row.optString("nom")).setContentText(body).setContentIntent(open).setAutoCancel(true).build());}catch(Exception ignored){}}
}
